buggy.described_examples:
import itertools
import importlib

import numpy as np

# Bind the module the examples call `tools`; locate whichever module exposes
# matrix_rank in this revision.
tools = None
for _name in ("statsmodels.tools.tools", "statsmodels.tools.linalg", "statsmodels.tools"):
    try:
        _mod = importlib.import_module(_name)
    except Exception:
        continue
    if hasattr(_mod, "matrix_rank"):
        tools = _mod
        break


DESC1 = 'tools.matrix_rank(exog[:, list(cols)], method="qr") for cols in itertools.permutations(range(3)), where x = 1e3 * np.arange(1.0, 41.0) / 7.0 and exog = np.column_stack((np.ones(40), x, 2.0 * x))'
DESC2 = 'tools.matrix_rank(exog[:, list(cols)], method=method) for each cols permutation of the 3-column exog, for method in ["ip", "qr", "svd"]'

x = 1e3 * np.arange(1.0, 41.0) / 7.0
exog = np.column_stack((np.ones(40), x, 2.0 * x))
perms = list(itertools.permutations(range(3)))

try:
    out = {}
    for cols in perms:
        out[repr(list(cols))] = int(tools.matrix_rank(exog[:, list(cols)], method="qr"))
    probe(DESC1, out)
except Exception as e:
    probe_exception(DESC1, e)

try:
    out = {}
    for cols in perms:
        row = {}
        for method in ["ip", "qr", "svd"]:
            row[method] = int(tools.matrix_rank(exog[:, list(cols)], method=method))
        out[repr(list(cols))] = row
    probe(DESC2, out)
except Exception as e:
    probe_exception(DESC2, e)

